(3766460, 532781, 27133, '<td valign="top">Good candid.</td>', 'Good candid.', '2007-06-11 06:07:53.000000', NULL, 1),
(3766461, 533187, 8522, '<td valign="top">Doesn''t have the feel of a candid shot, it feels far more like a portrait. Nice light. The hand and wrist feel awkward in the composition.</td>', 'Doesn''t have the feel of a candid shot, it feels far more like a portrait. Nice light. The hand and wrist feel awkward in the composition.', '2007-06-11 06:08:00.000000', NULL, 1),
