(3766486, 531575, 27133, '<td valign="top">Cute and good colours on the butterfly.</td>', 'Cute and good colours on the butterfly.', '2007-06-11 06:13:06.000000', NULL, 1),
(3766488, 529607, 8522, '<td valign="top">This looks like it''s been NeatImaged to death. The texture on the face is awful. Either that, or an ill-advised filter. Not sure about the composition, and it''s usually not good to chop off at the elbow.</td>', 'This looks like it''s been NeatImaged to death. The texture on the face is awful. Either that, or an ill-advised filter. Not sure about the composition, and it''s usually not good to chop off at the elbow.', '2007-06-11 06:13:11.000000', NULL, 1),
(3766490, 533203, 33352, '<td valign="top">no impact...</td>', 'no impact...', '2007-06-11 06:13:32.000000', NULL, 1),
