(3782143, 533198, 69776, '<td valign="top">Lol nice statue, teh window is a bit washed out an a distraction, good luck</td>', 'Lol nice statue, teh window is a bit washed out an a distraction, good luck', '2007-06-14 06:02:19.000000', NULL, 1),
(3782180, 533178, 52285, '<td valign="top">My favourite in the contest, inspired capture and really appropriate title. 10</td>', 'My favourite in the contest, inspired capture and really appropriate title. 10', '2007-06-14 06:48:45.000000', NULL, 1),
(3782196, 532223, 65964, '<td valign="top">I would like to see it bigger. Nicely done tho</td>', 'I would like to see it bigger. Nicely done tho', '2007-06-14 07:11:28.000000', NULL, 1),
