INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3791449, 533083, 50695, '<td valign="top">nice motion blur on the spongehand. 7</td>', 'nice motion blur on the spongehand. 7', '2007-06-16 13:48:47.000000', NULL, 1),
(3791450, 532312, 50695, '<td valign="top">great title! 7</td>', 'great title! 7', '2007-06-16 13:48:52.000000', NULL, 1),
